<script setup lang="ts">
import type {SpellBuilder,OptionBuilder} from '../../../shared/entry-builders'
import RuleBenefitsEditor from './RuleBenefitsEditor.vue'
import {DAMAGE_TYPES,benefitTitle} from '../../../shared/rule-benefits'
import {ABILITY_KEYS} from '../../lib/calc'
const props=defineProps<{kind:string;step:string;spell?:SpellBuilder;option?:OptionBuilder;benefits:unknown[];spellChoices?:{index:string;name:string}[]}>()
const emit=defineEmits<{benefits:[rows:unknown[]]}>()
const schools=['abjuration','conjuration','divination','enchantment','evocation','illusion','necromancy','transmutation']
const classes=['bard','cleric','druid','paladin','ranger','sorcerer','warlock','wizard']
function lines(event:Event){return (event.target as HTMLTextAreaElement).value.split('\n').map(v=>v.trim()).filter(Boolean)}
function schedule(value:Record<string,string>,event:Event){const rows=(event.target as HTMLTextAreaElement).value.split('\n').filter(v=>v.trim());for(const key of Object.keys(value))delete value[key];for(const row of rows){const match=row.match(/^\s*(\d+)\s*[:=]\s*(.+)$/);if(match)value[match[1]!]=match[2]!.trim();else value[row]=''}}
</script>
<template><section class="hw-panel hw-editor entry-reference-builder">
 <template v-if="step==='benefits'"><RuleBenefitsEditor :kind="kind" :spell-choices="spellChoices" :model-value="benefits" @update:model-value="emit('benefits',$event)" /></template>
 <template v-else-if="spell">
  <template v-if="step==='identity'"><h2>Spell</h2><p class="hw-hint">Edit the spell's identity and rules, with its current values already filled in.</p><div class="hw-form-grid"><label>Spell name<input v-model="spell.name" maxlength="200" required /></label><label>Spell level<select v-model.number="spell.level" aria-label="Spell level"><option v-for="n in 10" :key="n" :value="n-1">{{n===1?'Cantrip':n-1}}</option></select></label><label>School<select v-model="spell.school" aria-label="School"><option v-if="!schools.includes(spell.school)" :value="spell.school">{{benefitTitle(spell.school)}}</option><option v-for="s in schools" :key="s" :value="s">{{benefitTitle(s)}}</option></select></label></div><label>Rules & description<textarea v-model="spell.description" rows="9" /></label><label>At higher levels<textarea v-model="spell.higherLevel" rows="4" /></label></template>
  <template v-else-if="step==='casting'"><h2>Casting</h2><div class="hw-form-grid"><label>Casting time<input v-model="spell.castingTime" placeholder="1 action" /></label><label>Range<input v-model="spell.range" placeholder="60 feet" /></label><label>Duration<input v-model="spell.duration" placeholder="Instantaneous" /></label></div><div class="hw-check-group"><label><input v-model="spell.ritual" type="checkbox" /> Ritual</label><label><input v-model="spell.concentration" type="checkbox" /> Concentration</label></div><fieldset class="hw-check-group"><legend>Components</legend><label v-for="c in ['V','S','M']" :key="c"><input v-model="spell.components" type="checkbox" :value="c" />{{{V:'Verbal',S:'Somatic',M:'Material'}[c]}}</label></fieldset><label>Material components<input v-model="spell.material" /></label><fieldset class="hw-check-group"><legend>Class spell lists</legend><label v-for="c in [...new Set([...classes,...spell.classes])]" :key="c"><input v-model="spell.classes" type="checkbox" :value="c" />{{benefitTitle(c)}}</label></fieldset></template>
  <template v-else-if="step==='effects'"><h2>Targets & effects</h2><div class="hw-form-grid"><label>Attack roll<select v-model="spell.attackType" aria-label="Attack roll"><option value="">No spell attack</option><option value="melee">Melee spell attack</option><option value="ranged">Ranged spell attack</option></select></label><label>Saving throw<select v-model="spell.saveAbility" aria-label="Saving throw"><option value="">No saving throw</option><option v-for="a in ABILITY_KEYS" :key="a" :value="a">{{benefitTitle(a)}}</option></select></label><label v-if="spell.saveAbility">Successful save<input v-model="spell.saveSuccess" placeholder="half, none, or special" /></label><label>Damage type<select v-model="spell.damageType" aria-label="Damage type"><option value="">No damage type</option><option v-if="spell.damageType&&!DAMAGE_TYPES.includes(spell.damageType as any)" :value="spell.damageType">{{spell.damageType}}</option><option v-for="d in DAMAGE_TYPES" :key="d" :value="d">{{benefitTitle(d)}}</option></select></label><label>Area shape<select v-model="spell.areaType" aria-label="Area shape"><option value="">No area</option><option v-for="s in ['sphere','cube','cylinder','line','cone','radius']" :key="s">{{s}}</option></select></label><label v-if="spell.areaType">Area size (ft.)<input v-model.number="spell.areaSize" type="number" min="0" max="100000" /></label></div><div class="hw-form-grid"><label>Damage progression<textarea :value="Object.entries(spell.damage).map(([level,dice])=>`${level}: ${dice}`).join('\n')" rows="6" placeholder="1: 2d6&#10;2: 3d6" @input="schedule(spell.damage,$event)" /><small class="hw-hint">One level and dice expression per line. Existing character-level or slot-level scaling is retained.</small></label><label>Healing progression<textarea :value="Object.entries(spell.healing).map(([level,dice])=>`${level}: ${dice}`).join('\n')" rows="6" placeholder="1: 1d8 + MOD" @input="schedule(spell.healing,$event)" /></label></div><p class="hw-hint">Casting, targeting, dice rolls and spell costs remain under your control. Add supported ongoing effects in Benefits.</p></template>
 </template>
 <template v-else-if="option">
  <template v-if="step==='identity'"><h2>{{kind==='languages'?'Language':kind==='backgrounds'?'Background':'Identity & rules'}}</h2><label>Name<input v-model="option.name" required maxlength="200" /></label><label>Rules & description<textarea v-model="option.description" rows="9" /></label><label v-if="kind!=='languages'">Prerequisites<textarea v-model="option.prerequisites" rows="3" placeholder="Required level, ability, class or other conditions" /></label><template v-if="kind==='languages'"><div class="hw-form-grid"><label>Language type<input v-model="option.languageType" placeholder="Standard or exotic" /></label><label>Script<input v-model="option.script" /></label></div><label>Typical speakers<textarea :value="option.typicalSpeakers.join('\n')" rows="4" @input="option.typicalSpeakers=lines($event)" /></label></template></template>
  <template v-else-if="step==='options'"><h2>{{kind==='backgrounds'?'Background feature & equipment':'Features & choices'}}</h2><template v-if="kind==='backgrounds'"><label>Feature name<input v-model="option.featureName" /></label><label>Feature description<textarea v-model="option.featureDescription" rows="7" /></label><label>Starting equipment notes<textarea v-model="option.equipment" rows="4" /></label></template><template v-else><label>Options offered<textarea :value="option.options.join('\n')" rows="8" placeholder="One named option per line" @input="option.options=lines($event)" /></label><label v-if="kind==='selections'">Number of options to choose<input v-model.number="option.choose" type="number" min="1" max="200" /></label><p class="hw-hint">Describe choices here. Add supported mechanical grants in Benefits; prerequisites and player choices require review.</p></template></template>
 </template>
 <template v-if="step==='review'"><h2>Review entry</h2><h3>{{spell?.name??option?.name}}</h3><p class="sheet-prose">{{spell?.description??option?.description}}</p><p class="hw-hint">Save the personal edition below. Existing characters keep their current rules until you review and apply the changes to each character.</p></template>
</section></template>
